script:
(function () {
  'use strict';
  // HECM (FHA-insured) reverse mortgage estimate.
  //   Maximum claim amount (MCA) = lesser of home value and the national HECM limit.
  //   Principal limit = MCA x principal limit factor (PLF). PLFs come from HUD tables by youngest
  //     borrower's age and the expected rate; they are not embedded here - the user enters theirs.
  //   Mandatory obligations = 2% upfront MIP on the MCA + origination fee + other closing costs
  //     + existing mortgage payoff. Net principal limit = principal limit - mandatory obligations.
  //   First-year draw limit = greater of 60% of the principal limit or mandatory obligations + 10%
  //     of the principal limit (never more than the principal limit).
  //   Origination fee cap = 2% of the first $200,000 of MCA + 1% above, minimum $2,500, max $6,000.
  //   Balance grows monthly at (interest rate + 0.5% annual MIP) / 12; unused line of credit grows
  //     at the same rate. Term/tenure payments: annuity due on the net principal limit at that
  //     rate over the term (tenure = to the youngest borrower's age 100).
  // Verified (Node, scratchpad tests/w3b2e): $400,000 home, 40% PLF, $50,000 payoff, $3,000 costs:
  //   MCA $400,000, principal limit $160,000, MIP $8,000, origination cap $6,000, mandatory
  //   $67,000, first-year limit $96,000 (60%), lump sum $29,000, net principal limit $93,000;
  //   balance after 12 months $96,000 x (1 + 7%/12)^12 = $102,940 at a 6.5% rate. Term 10 yrs ->
  //   $1,073.55/month (annuity due; drawing it monthly from $93,000 growing at 7%/12 leaves $0.00).
  //   Origination cap: $100,000 MCA -> $2,500; $300,000 -> $5,000; $400,000+ -> $6,000; a higher
  //   entered fee is capped. MCA capped at $1,249,125 for a $2,000,000 home.
  //
  // ---- 2026 HECM CONSTANTS (FHA case numbers assigned in calendar 2026) --------------------
  // Maximum claim amount limit $1,249,125: HUD Mortgagee Letter 2025-22 (Dec 11, 2025), 150% of
  //   the $832,750 national conforming limit.
  // Upfront MIP 2% of MCA and annual MIP 0.5% of the outstanding balance: HUD Mortgagee Letter
  //   2017-12 (effective October 2, 2017), still current.
  // Origination fee cap: 12 U.S.C. 1715z-20(r) / 24 CFR 206.31. First-year 60% draw limit:
  //   HUD Mortgagee Letter 2013-27. Minimum age 62: 24 CFR 206.33.
  var HECM_YEAR = 2026;
  var MCA_LIMIT = 1249125;
  var UPFRONT_MIP = 0.02, ANNUAL_MIP = 0.005;
  var ORIG_MIN = 2500, ORIG_MAX = 6000, ORIG_TIER = 200000, ORIG_RATE_1 = 0.02, ORIG_RATE_2 = 0.01;
  var FIRST_YEAR_SHARE = 0.6, FIRST_YEAR_EXTRA = 0.1, MIN_AGE = 62;
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function originationCap(mca) {
    var fee = ORIG_RATE_1 * Math.min(mca, ORIG_TIER) + ORIG_RATE_2 * Math.max(0, mca - ORIG_TIER);
    return Math.max(ORIG_MIN, Math.min(ORIG_MAX, fee));
  }

  function annuityDue(pv, monthlyRate, months) {
    if (pv <= 0 || months <= 0) return 0;
    if (monthlyRate === 0) return pv / months;
    return pv * monthlyRate / ((1 - Math.pow(1 + monthlyRate, -months)) * (1 + monthlyRate));
  }

  function calculate(o) {
    var mca = Math.min(o.value, MCA_LIMIT);
    var pl = mca * o.plf;
    var mip = UPFRONT_MIP * mca;
    var origMax = originationCap(mca);
    var orig = o.orig === null ? origMax : Math.min(o.orig, origMax);
    var mandatory = mip + orig + o.costs + o.payoff;
    var net = Math.max(0, pl - mandatory);
    var shortfall = Math.max(0, mandatory - pl);
    var firstYear = Math.min(pl, Math.max(FIRST_YEAR_SHARE * pl, mandatory + FIRST_YEAR_EXTRA * pl));
    var c = (o.rate + ANNUAL_MIP) / 12;
    var cash = 0, loc = 0, payment = 0, months = 0;
    if (o.plan === 'lump') { cash = Math.min(net, Math.max(0, firstYear - mandatory)); loc = net - cash; }
    else if (o.plan === 'loc') { loc = net; }
    else {
      months = o.plan === 'tenure' ? Math.max(1, Math.round((100 - o.age) * 12)) : Math.round(o.term * 12);
      payment = annuityDue(net, c, months);
    }
    // monthly projection
    var bal = Math.min(pl, mandatory) + cash, rows = [], received = cash, yrInterest = 0, yrMip = 0;
    var totalInterest = 0, totalMip = 0;
    for (var m = 1; m <= o.years * 12; m++) {
      if (payment > 0 && m <= months) { bal += payment; received += payment; }
      var interest = bal * o.rate / 12, ins = bal * ANNUAL_MIP / 12;
      bal += interest + ins;
      loc *= 1 + c;
      yrInterest += interest; yrMip += ins;
      if (m % 12 === 0) {
        var home = o.value * Math.pow(1 + o.appreciation, m / 12);
        rows.push({ year: m / 12, age: o.age + m / 12, received: received, interest: yrInterest, mip: yrMip,
                    balance: bal, home: home, equity: home - bal, loc: loc });
        totalInterest += yrInterest; totalMip += yrMip;
        yrInterest = 0; yrMip = 0;
      }
    }
    return { mca: mca, pl: pl, mip: mip, origMax: origMax, orig: orig, mandatory: mandatory, net: net,
             shortfall: shortfall, firstYear: firstYear, cash: cash, loc: loc, payment: payment, months: months,
             startLoc: o.plan === 'lump' ? net - cash : (o.plan === 'loc' ? net : 0),
             rows: rows, totalInterest: totalInterest, totalMip: totalMip };
  }

  var IDS = ['rmHeadline', 'rmPrincipalLimit', 'rmNet', 'rmMca', 'rmMip', 'rmOrigOut', 'rmCostsOut',
             'rmPayoffOut', 'rmMandatory', 'rmFirstYear', 'rmLocOut', 'rmEndBalance', 'rmEndEquity', 'rmEndCost'];

  function clear() {
    IDS.forEach(function (id) { setText(id, '–'); });
    el('rmProjection').innerHTML = '';
    el('rmNote').hidden = true;
    setText('rmOrigHint', 'Leave blank to use the HUD maximum.');
  }

  function update() {
    var o = {
      value: read('rmValue', NaN), age: read('rmAge', NaN), plf: read('rmPlf', NaN) / 100, rate: read('rmRate', NaN) / 100,
      payoff: read('rmPayoff', 0), plan: el('rmPlan').value, term: read('rmTerm', NaN),
      orig: read('rmOrig', null), costs: read('rmCosts', 0), appreciation: read('rmAppreciation', 0) / 100,
      years: read('rmYears', NaN)
    };
    var termPlan = o.plan === 'term';
    el('rmTermWrap').hidden = !termPlan;
    var err = el('rmError'), msg = '';
    var required = [o.value, o.age, o.plf, o.rate, o.years].concat(termPlan ? [o.term] : []);
    if (required.some(isNaN) || [o.payoff, o.costs, o.appreciation].some(isNaN) || (o.orig !== null && isNaN(o.orig))) msg = 'Fill in the home value, age, principal limit factor, rate and years using numbers.';
    else if (o.value <= 0 || o.value > 1e9) msg = 'Enter a home value above $0.';
    else if (o.age < MIN_AGE || o.age > 99) msg = 'The youngest borrower must be ' + MIN_AGE + ' to 99 for a HECM.';
    else if (o.plf <= 0 || o.plf > 0.9) msg = 'Enter a principal limit factor between 0% and 90%.';
    else if (o.rate < 0 || o.rate > 0.2) msg = 'Enter an interest rate from 0% to 20%.';
    else if (o.payoff < 0 || o.costs < 0 || (o.orig !== null && o.orig < 0) || o.payoff > 1e9 || o.costs > 1e9) msg = 'Amounts can\'t be negative.';
    else if (o.appreciation < -0.2 || o.appreciation > 0.2) msg = 'Enter a home value change from -20% to 20% a year.';
    else if (o.years < 1 || o.years > 40 || o.years !== Math.floor(o.years)) msg = 'Project 1 to 40 whole years.';
    else if (termPlan && (o.term < 1 || o.term > 40)) msg = 'Enter a payment term of 1 to 40 years.';
    err.hidden = !msg;
    if (msg) { err.textContent = msg; clear(); return; }

    var r = calculate(o);
    var label = el('rmHeadlineLabel');
    if (o.plan === 'lump') { label.textContent = 'Cash at closing'; setText('rmHeadline', money.format(r.cash)); }
    else if (o.plan === 'loc') { label.textContent = 'Line of credit'; setText('rmHeadline', money.format(r.net)); }
    else { label.textContent = o.plan === 'tenure' ? 'Monthly payment for life' : 'Monthly payment for ' + o.term + ' years'; setText('rmHeadline', cents.format(r.payment)); }
    setText('rmPrincipalLimit', money.format(r.pl));
    setText('rmNet', money.format(r.net));
    setText('rmMca', money.format(r.mca));
    setText('rmMip', money.format(r.mip));
    setText('rmOrigOut', money.format(r.orig));
    setText('rmCostsOut', money.format(o.costs));
    setText('rmPayoffOut', money.format(o.payoff));
    setText('rmMandatory', money.format(r.mandatory));
    setText('rmFirstYear', money.format(r.firstYear));
    setText('rmLocOut', money.format(r.startLoc));
    setText('rmOrigHint', 'Leave blank to use the HUD maximum: ' + money.format(r.origMax) + ' for this home.');
    var endRow = r.rows[r.rows.length - 1];
    setText('rmEndYears', o.years + (o.years === 1 ? ' year' : ' years'));
    setText('rmEndBalance', money.format(endRow.balance));
    setText('rmEndEquity', money.format(Math.max(0, endRow.equity)));
    setText('rmEndCost', money.format(r.totalInterest + r.totalMip));

    el('rmProjection').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + row.age + '</td><td>' + money.format(row.received) + '</td><td>' +
        money.format(row.interest + row.mip) + '</td><td>' + money.format(row.balance) + '</td><td>' +
        money.format(row.home) + '</td><td>' + money.format(Math.max(0, row.equity)) + '</td><td>' + money.format(row.loc) + '</td></tr>';
    }).join('');

    var notes = [];
    if (r.shortfall > 0) notes.push('Your existing mortgage and closing costs exceed the principal limit by ' + money.format(r.shortfall) + '. You would need to pay that difference at closing to qualify.');
    if (o.value > MCA_LIMIT) notes.push('Only the first ' + money.format(MCA_LIMIT) + ' of your home value counts — the ' + HECM_YEAR + ' HECM limit.');
    if (o.orig !== null && o.orig > r.origMax) notes.push('HUD caps the origination fee at ' + money.format(r.origMax) + ' for this home, so that amount is used.');
    if (o.plan === 'lump' && r.loc > 0) notes.push('The first-year limit holds back ' + money.format(r.startLoc) + ' as a line of credit you can draw after 12 months.');
    if (endRow.equity < 0) notes.push('By year ' + o.years + ' the balance is projected to exceed the home value. A HECM is non-recourse: the debt is repaid from the sale of the home and you or your heirs are not billed for the shortfall.');
    var note = el('rmNote');
    note.hidden = notes.length === 0;
    note.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
